<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/bootstrap.php';msp2RequireAccess();if(($_SERVER['REQUEST_METHOD']??'GET')!=='POST')msp2Redirect('tesoreria/conciliacion.php');
$cuenta=filter_input(INPUT_POST,'id_cuenta_tesoreria',FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);$fecha=trim((string)($_POST['fecha_cierre']??''));[$ok,$contado]=msp2NormalizeDecimalInput((string)($_POST['efectivo_contado']??''),2);$obs=msp2NormalizeText((string)($_POST['observaciones']??''));$d=DateTimeImmutable::createFromFormat('!Y-m-d',$fecha);
if(!$cuenta||!$ok||$contado===null||(float)$contado<0||!$d||$d->format('Y-m-d')!==$fecha||mb_strlen($obs)>500){msp2SetFlash('warning','Completa correctamente los datos del cierre.');msp2Redirect('tesoreria/conciliacion.php');}
try{$stmt=$conn->prepare('EXEC dbo.msp_tesoreria_cerrar_caja @id_cuenta_tesoreria=:cuenta,@fecha_cierre=:fecha,@efectivo_contado=:contado,@observaciones=:observaciones,@id_usuario=:usuario');$stmt->execute([':cuenta'=>(int)$cuenta,':fecha'=>$fecha,':contado'=>$contado,':observaciones'=>$obs!==''?$obs:null,':usuario'=>(int)$_SESSION['usuario']['id']]);$r=$stmt->fetch()?:[];$estado=(string)($r['estado_cierre']??'');msp2SetFlash($estado==='CUADRADO'?'success':'warning','Cierre #'.(int)($r['id_cierre_caja']??0).' registrado: '.$estado.'. Diferencia: $ '.number_format((float)($r['diferencia']??0),2,',','.').'.');}catch(Throwable $e){msp2SetFlash($e instanceof RuntimeException?'warning':'danger',$e instanceof RuntimeException?$e->getMessage():'No fue posible cerrar la caja.');}
msp2Redirect('tesoreria/conciliacion.php?fecha_caja='.rawurlencode($fecha));
